import { PortableText } from 'next-sanity';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { Section } from '@/components/ui/section';
import moduleProps from '@/lib/moduleProps';
import { cn } from '@/lib/utils';

export default function AccordionList({
  content,
  items,
  generateSchema,
  ...props
}: Partial<{
  content: any;
  items: {
    summary: string;
    content: any;
    _content?: any;
    open?: boolean;
    _open?: boolean;
  }[];
  generateSchema: boolean;
}> &
  Sanity.Module) {
  const defaultOpenItems = items
    ?.map(({ summary, content: _content, open }, index) =>
      open
        ? `accordion-item-${index}-${summary ? summary.substring(0, 20).replace(/\s+/g, '-').toLowerCase() : ''}`
        : null
    )
    .filter((item): item is string => item !== null);

  return (
    <Section
      className="space-y-4 text-center"
      {...(generateSchema && {
        itemScope: true,
        itemType: 'https://schema.org/FAQPage',
      })}
      {...moduleProps(props)}
    >
      {content && (
        <div className="prose prose-slate dark:prose-invert mx-auto text-muted-foreground">
          <PortableText
            value={content}
            components={{
              block: {
                normal: ({ children }) => (
                  <p className="text-muted-foreground text-lg">{children}</p>
                ),
                h2: ({ children }) => (
                  <h2 className="text-2xl font-bold md:text-3xl mb-3">{children}</h2>
                ),
                h3: ({ children }) => (
                  <h3 className="text-xl font-semibold md:text-2xl mb-3">{children}</h3>
                ),
                h4: ({ children }) => <h4 className="text-lg font-semibold mb-2">{children}</h4>,
              },
            }}
          />
        </div>
      )}

      <Accordion
        defaultValue={defaultOpenItems}
        className={cn('mx-auto w-full text-left')}
      >
        {items?.map(({ summary, content, open: _open }, index) => {
          // Create a stable key for the accordion item
          const itemKey = `accordion-item-${index}-${summary ? summary.substring(0, 20).replace(/\s+/g, '-').toLowerCase() : ''}`;
          return (
            <AccordionItem
              key={itemKey}
              value={itemKey}
              {...(generateSchema && {
                itemScope: true,
                itemProp: 'mainEntity',
                itemType: 'https://schema.org/Question',
              })}
            >
              <AccordionTrigger className="hover:text-primary hover:underline group [&>svg]:group-hover:text-primary">
                <span
                  {...(generateSchema && {
                    itemProp: 'name',
                  })}
                >
                  {summary}
                </span>
              </AccordionTrigger>
              {generateSchema && (
                <div
                  className="sr-only"
                  itemScope
                  itemProp="acceptedAnswer"
                  itemType="https://schema.org/Answer"
                >
                  <div className="sr-only" itemProp="text">
                    <PortableText value={content} />
                  </div>
                </div>
              )}

              <AccordionContent className="prose prose-slate dark:prose-invert max-w-none">
                <PortableText value={content} />
              </AccordionContent>
            </AccordionItem>
          );
        })}
      </Accordion>
    </Section>
  );
}

import { stegaClean } from 'next-sanity';
import { Fragment } from 'react';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';
import { Section } from '@/components/ui/section';
import resolveUrl from '@/lib/resolveUrl';

export default async function Breadcrumbs({
  crumbs,
  hideCurrent,
  currentPage,
}: Partial<{
  crumbs: Sanity.Link[];
  hideCurrent?: boolean;
  currentPage: Sanity.Page | Sanity.BlogPost | Sanity.ComponentLibrary;
}>) {
  return (
    <Section as={Breadcrumb} className="py-4 text-sm" spacing="none">
      <BreadcrumbList itemScope itemType="https://schema.org/BreadcrumbList">
        {crumbs?.map((crumb, index) => (
          <Fragment key={(crumb as any)._key || index}>
            <BreadcrumbItem
              itemProp="itemListElement"
              itemScope
              itemType="https://schema.org/ListItem"
              className="line-clamp-1"
            >
              <BreadcrumbLink
                href={
                  crumb.internal
                    ? resolveUrl(crumb.internal, { base: false })
                    : crumb.external
                      ? stegaClean(crumb.external)
                      : '/'
                }
                className="hover:underline"
                itemProp="item"
              >
                <span itemProp="name">
                  {stegaClean(crumb.label || crumb.internal?.title || crumb.external)}
                </span>
                <meta itemProp="position" content={(crumbs?.indexOf(crumb) + 1).toString()} />
              </BreadcrumbLink>
            </BreadcrumbItem>

            {(crumbs?.indexOf(crumb) < crumbs.length - 1 || !hideCurrent) && (
              <BreadcrumbSeparator />
            )}
          </Fragment>
        ))}

        {!hideCurrent && currentPage && (
          <BreadcrumbItem
            itemProp="itemListElement"
            itemScope
            itemType="https://schema.org/ListItem"
            className="line-clamp-1"
          >
            <BreadcrumbPage>
              <span itemProp="name">{currentPage.title || currentPage.metadata?.title}</span>
              <meta itemProp="position" content={((crumbs?.length || 0) + 1).toString()} />
            </BreadcrumbPage>
          </BreadcrumbItem>
        )}
      </BreadcrumbList>
    </Section>
  );
}

