// Define types based on schema
type Tier = {
  _key: string;
  name: string;
  price?: string;
  description?: string;
  popular?: boolean;
  cta?: any; // Sanity CTA type
};

type FeatureTier =
  | {
      type: 'string' | 'boolean';
      title: string | boolean;
    }
  | string
  | boolean;

type FeatureItem = {
  _key: string;
  name: string;
  tooltip?: string;
  tiers: FeatureTier[];
  subItems?: FeatureItem[];
};

type FeatureCategory = {
  _key: string;
  category: string;
  items: FeatureItem[];
};

type PricingComparisonProps = {
  title?: string;
  description?: string;
  tiers?: Tier[];
  featureCategories?: FeatureCategory[];
} & Sanity.Module;

export default function PricingComparison({
