// Define the VideoHero data structure
type VideoHero = {
  _type: 'videoHero';
  _key: string;
  type: 'mux' | 'youtube';
  videoId?: string;
  muxVideo?: {
    asset?: {
      playbackId?: string;
      data?: {
        playback_ids?: Array<{ id: string }>;
      };
    };
    playbackId?: string;
  };
