// Error Component
const VideoError = ({
  error,
  type,
  onBackClick,
}: {
  error: string | null;
  type?: string;
  onBackClick: () => void;
}) => {
  return (
    <div className="flex items-center justify-center h-full bg-muted text-foreground text-center p-4">
      <div>
        <p className="text-xl font-semibold mb-2">Video Error</p>
        <p>{error || `Could not find a valid video ID for this ${type || ''} video.`}</p>
        <button
          type="button"
          onClick={onBackClick}
          className="mt-4 px-4 py-2 bg-primary text-primary-foreground rounded"
        >
          Back to Thumbnail
        </button>
      </div>
    </div>
  );
};

export default function VideoHero({ data }: VideoHeroProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Handle different video types with custom hooks
  const youtube = useYouTubeVideo(data?.type === 'youtube' ? data.videoId : undefined);
  const mux = useMuxVideo(data);

  // Generate thumbnail URL
  let thumbnailUrl =
    (data?.thumbnail as any)?.src ||
    (data?.thumbnail as any)?.url ||
    (data?.thumbnail ? urlFor(data.thumbnail as any).url() : null);

  // Fallback to automatic thumbnails if manual one is missing
  if (!thumbnailUrl) {
    if (data?.type === 'mux' && mux.videoId) {
      thumbnailUrl = `https://image.mux.com/${mux.videoId}/thumbnail.jpg?width=1920&height=1080&fit_mode=preserve`;
    } else if (data?.type === 'youtube' && youtube.videoId) {
      thumbnailUrl = `https://img.youtube.com/vi/${youtube.videoId}/maxresdefault.jpg`;
    }
  }

  const handlePlayClick = () => {
    setIsPlaying(true);
  };

  const handleError = (err: any) => {
    setError(`Video player error: ${err}`);
  };

  // Combined error state
  const videoError =
    error ||
    (data?.type === 'youtube' ? youtube.error : null) ||
    (data?.type === 'mux' ? mux.error : null);

  return (
    <Section width="full" spacing="none" className="relative w-full h-[80dvh] bg-muted">
      {/* SEO-friendly metadata */}
      <div className="hidden">
        <h1>{data?.title || 'Video'}</h1>
      </div>

      {!isPlaying ? (
        // Thumbnail view
        <button
          type="button"
          className="relative w-full h-full cursor-pointer bg-muted"
          onClick={handlePlayClick}
          aria-label="Play video"
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              handlePlayClick();
            }
          }}
        >
          {thumbnailUrl ? (
            <Image
              src={thumbnailUrl}
              alt={data?.title || 'Video thumbnail'}
              fill
              priority
              className="object-cover"
            />
          ) : (
            <div className="absolute inset-0 flex items-center justify-center text-muted-foreground">
              <p>No thumbnail available</p>
            </div>
          )}
          <div className="absolute inset-0 bg-background/30 flex items-center justify-center">
            <span className="w-16 h-16 bg-primary text-primary-foreground rounded-full flex items-center justify-center">
              {/* Play icon */}
              <svg className="w-8 h-8" viewBox="0 0 24 24">
                <title>Play video icon</title>
                <path d="M8 5v14l11-7z" fill="currentColor" />
              </svg>
            </span>
          </div>
        </button>
      ) : (
        // Video player
        <div className="relative w-full h-full overflow-hidden bg-muted">
          {videoError ? (
            <VideoError
              error={videoError}
              type={data?.type}
              onBackClick={() => setIsPlaying(false)}
            />
          ) : data?.type === 'mux' && mux.videoId ? (
            <MuxVideoPlayer playbackId={mux.videoId} title={data.title} onError={handleError} />
          ) : data?.type === 'youtube' && youtube.videoId ? (
            <YouTubePlayer videoId={youtube.videoId} title={data.title} />
          ) : (
            <VideoError error={null} type={data?.type} onBackClick={() => setIsPlaying(false)} />
          )}
        </div>
      )}
    </Section>
  );
}

import Modules from '@/ui/modules';
import ComponentGalleryClient, { type GalleryComponent } from './ComponentGallery.client';

type GalleryItem = Sanity.Module & {
  _key: string;
};

type Group = {
  _key: string;
  title: string;
  items: GalleryItem[];
};

export default function ComponentGallery({
  intro,
  groups,
}: Partial<{
  intro: any[];
  groups: Group[];
}>) {
  if (!groups?.length) return null;

  // Helper to extract title from portable text content
  const getContentTitle = (content: any) => {
    if (!content || !Array.isArray(content)) return null;
    // Try to find a heading
    const heading = content.find(
      (block: any) => block._type === 'block' && ['h1', 'h2', 'h3'].includes(block.style)
    );
    if (heading?.children?.[0]?.text) return heading.children[0].text;

    // Fallback to first text block
    const firstBlock = content.find((block: any) => block._type === 'block');
    return firstBlock?.children?.[0]?.text;
  };

  // Flatten groups into a single list of components with category info
  const components: GalleryComponent[] = groups.flatMap(
    (group) =>
      group.items?.map((item) => {
        // item IS the module now

        // Infer title/name from module data
        const title =
          // @ts-expect-error - dynamic access
          item.title ||
          // @ts-expect-error - dynamic access
          item.summary ||
          // @ts-expect-error - dynamic access
          item.pretitle ||
          // @ts-expect-error - dynamic access
          getContentTitle(item.content) ||
          item._type;

        return {
          id: item._key,
          name: title || 'Untitled',
          // @ts-expect-error - dynamic access
          description: item.description || item.subtitle || '',
          category: group.title,
          moduleType: item._type,
          children: <Modules modules={[item]} />,
        };
      }) || []
  );

  return <ComponentGalleryClient intro={intro} components={components} />;
}

import { groq, stegaClean } from 'next-sanity';
import { Suspense } from 'react';
import { Section } from '@/components/ui/section';
import { fetchSanityLive } from '@/sanity/lib/fetch';
import FilterList from '../LatestArticles/FilterList';
import PostPreview from '../PostPreview';
import PostPreviewLarge from '../PostPreviewLarge';
import Paginated from './Paginated';
import sortFeaturedPosts from './sortFeaturedPosts';

export default async function BlogFrontpage({
  mainPost,
  showFeaturedPostsFirst,
  itemsPerPage,
  posts: postsProp,
}: Partial<{
  mainPost: 'recent' | 'featured';
  showFeaturedPostsFirst: boolean;
  itemsPerPage: number;
  posts?: Sanity.BlogPost[];
}>) {
  const posts =
    postsProp ||
    (await fetchSanityLive<Sanity.BlogPost[]>({
      query: groq`*[_type == 'blog.post']|order(publishDate desc){
			_type,
			_id,
			featured,
			metadata,
			categories[]->,
			authors[]->,
			publishDate,
		}`,
    }));

  const [firstPost, ...otherPosts] =
    stegaClean(mainPost) === 'featured' ? sortFeaturedPosts(posts) : posts;

  return (
    <Section className="space-y-12">
      <PostPreviewLarge post={firstPost} />

      <hr />

      <FilterList />

      <Suspense
        fallback={
          <ul className="grid gap-x-8 gap-y-12 sm:grid-cols-[repeat(auto-fill,minmax(300px,1fr))]">
            {Array.from({ length: itemsPerPage ?? 6 }).map((_, i) => (
              <li key={`skeleton-${i}`}>
                <PostPreview skeleton />
              </li>
            ))}
          </ul>
        }
      >
        <Paginated
          posts={sortFeaturedPosts(otherPosts, showFeaturedPostsFirst)}
          itemsPerPage={itemsPerPage}
        />
      </Suspense>
    </Section>
  );
}

import { groq, PortableText, stegaClean } from 'next-sanity';
import { Suspense } from 'react';
import { Section } from '@/components/ui/section';
import { cn } from '@/lib/utils';
import { fetchSanityLive } from '@/sanity/lib/fetch';
import FilterList from '@/ui/modules/blog/LatestArticles/FilterList';
import Pretitle from '@/ui/Pretitle';
import PostPreview from '../PostPreview';
import List from './List';

export default async function LatestArticles({
  pretitle,
  intro,
  layout,
  limit,
  showFeaturedPostsFirst,
  displayFilters,
  filteredCategory,
  posts: postsProp,
}: Partial<{
  pretitle: string;
  intro: any;
  layout: 'grid' | 'carousel';
  limit: number;
  showFeaturedPostsFirst: boolean;
  displayFilters: boolean;
  filteredCategory: Sanity.BlogCategory;
  posts?: Sanity.BlogPost[];
}>) {
  const posts =
    postsProp ||
    (await fetchSanityLive<Sanity.BlogPost[]>({
      query: groq`
			*[
				_type == 'blog.post'
				${filteredCategory ? '&& $filteredCategory in categories[]->._id' : ''}
			]|order(
				${showFeaturedPostsFirst ? 'featured desc, ' : ''}
				publishDate desc
			)
			${limit ? `[0...${limit}]` : ''}
			{
				...,
				categories[]->,
				authors[]->
			}
		`,
      params: {
        filteredCategory: filteredCategory?._id || '',
        limit: limit ?? 0,
      },
    }));

  const listClassName = cn(
    'items-stretch gap-x-8 gap-y-12',
    stegaClean(layout) === 'grid'
      ? 'grid md:grid-cols-[repeat(auto-fill,minmax(300px,1fr))]'
      : 'carousel max-xl:full-bleed md:overflow-fade-r pb-4 [--size:320px] max-xl:px-4'
  );

  const sizes =
    stegaClean(layout) === 'grid'
      ? '(min-width: 1024px) 33vw, (min-width: 768px) 50vw, 100vw'
      : '320px';

  return (
    <Section className="space-y-8">
      {intro && (
        <header className="richtext">
          <Pretitle>{pretitle}</Pretitle>
          <PortableText value={intro} />
        </header>
      )}

      {displayFilters && !filteredCategory && <FilterList />}

      <Suspense
        fallback={
          <ul className={listClassName}>
            {Array.from({ length: limit ?? 6 }).map((_, i) => (
              <li key={`skeleton-${i}`}>
                <PostPreview skeleton />
              </li>
            ))}
          </ul>
        }
      >
        <List posts={posts} className={listClassName} sizes={sizes} />
      </Suspense>
    </Section>
  );
}
